import { Theme } from '@/theme'
import { ViewStyle, TextStyle, ImageStyle } from 'react-native'

type StyleFn = (
	theme: Theme,
	isDark: boolean
) => ViewStyle | TextStyle | ImageStyle
type StyleValue = ViewStyle | TextStyle | ImageStyle | StyleFn

export function defineStyles<T extends Record<string, StyleValue>>(
	styles: T
): T {
	return styles
}
